1	package com.example.starter.pump.service;
2	
3	import com.example.starter.pump.core.TimeProvider;
4	import com.example.starter.pump.domain.StoredRequest;
5	import com.example.starter.pump.error.ApiException;
6	import com.example.starter.pump.repo.IdempotentRepository;
7	import com.fasterxml.jackson.databind.ObjectMapper;
8	import org.springframework.stereotype.Component;
9	
10	import java.util.Optional;
11	import java.util.function.Supplier;
12	
13	/**
14	 * 幂等执行模板：以 requestId 为键，指纹覆盖 requestId 与全部业务字段。
15	 *
16	 * <p>语义：
17	 * <ul>
18	 *   <li>同键同参：返回首次结果（重放），不重复执行业务；</li>
19	 *   <li>同键异参：抛 409，不执行任何业务，不改变泵站状态；</li>
20	 *   <li>首次：占位抢占成功后执行业务并回写首次结果，与业务处于同一事务。</li>
21	 * </ul>
22	 */
23	@Component
24	public class IdempotencyTemplate {
25	
26	    private final IdempotentRepository repository;
27	    private final ObjectMapper objectMapper;
28	    private final TimeProvider timeProvider;
29	
30	    public IdempotencyTemplate(IdempotentRepository repository, ObjectMapper objectMapper,
31	                               TimeProvider timeProvider) {
32	        this.repository = repository;
33	        this.objectMapper = objectMapper;
34	        this.timeProvider = timeProvider;
35	    }
36	
37	    /** 幂等执行结果：value 为业务返回体，replayed 标记本次是否命中同键重放。 */
38	    public record Outcome<T>(T value, boolean replayed) {
39	    }
40	
41	    /**
42	     * 幂等执行业务并返回结果（首次或重放）。
43	     *
44	     * @param requestId     幂等键
45	     * @param bizType       业务类型 WARNING/PUMP_TASK/ARCHIVE
46	     * @param fingerprint   requestId+全部业务字段的指纹
47	     * @param successStatus 首次受理HTTP状态码
48	     * @param action        首次受理时执行的业务
49	     * @param resultType    结果类型，用于重放反序列化
50	     */
51	    public <T> Outcome<T> execute(String requestId, String bizType, String fingerprint,
52	                                  int successStatus, Supplier<T> action, Class<T> resultType) {
53	        Optional<StoredRequest> existing = repository.find(requestId);
54	        if (existing.isPresent()) {
55	            return new Outcome<>(replayOrConflict(existing.get(), fingerprint, resultType), true);
56	        }
57	        boolean acquired = repository.tryAcquire(requestId, bizType, fingerprint,
58	                timeProvider.now());
59	        if (!acquired) {
60	            StoredRequest concurrent = repository.find(requestId)
61	                    .orElseThrow(() -> new IllegalStateException("幂等占位冲突但重查为空: " + requestId));
62	            return new Outcome<>(replayOrConflict(concurrent, fingerprint, resultType), true);
63	        }
64	        T result = action.get();
65	        repository.saveResult(requestId, successStatus, writeJson(result));
66	        return new Outcome<>(result, false);
67	    }
68	
69	    private <T> T replayOrConflict(StoredRequest stored, String fingerprint, Class<T> resultType) {
70	        if (!stored.fingerprint().equals(fingerprint)) {
71	            throw ApiException.conflict("requestId=" + stored.requestId()
72	                    + " 已用于不同业务参数，拒绝受理且不改变泵站状态");
73	        }
74	        if (stored.responseBody() == null) {
75	            throw new IllegalStateException("幂等记录缺少首次结果: " + stored.requestId());
76	        }
77	        try {
78	            return objectMapper.readValue(stored.responseBody(), resultType);
79	        } catch (Exception e) {
80	            throw new IllegalStateException("幂等首次结果反序列化失败: " + stored.requestId(), e);
81	        }
82	    }
83	
84	    private String writeJson(Object result) {
85	        try {
86	            return objectMapper.writeValueAsString(result);
87	        } catch (Exception e) {
88	            throw new IllegalStateException("幂等首次结果序列化失败", e);
89	        }
90	    }
91	}
