22	 * 恰满30分钟无数据失联派单、归档后迟到数据只记迟到事件。
23	 */
24	@Service
25	public class LevelService {
26	
27	    /** 失联阈值：距末次液位恰满30分钟即判定（等于30分钟合法）。 */
28	    static final Duration MISS_CONTACT_AFTER = Duration.ofMinutes(30);
29	
30	    private final CatalogRepository catalogRepository;
31	    private final PumpdownEventRepository eventRepository;
32	    private final LevelReadingRepository levelRepository;
33	    private final MissContactOrderRepository missContactRepository;
34	    private final PumpCommandService pumpCommandService;
35	    private final TimeProvider timeProvider;
