37	    public LevelService(CatalogRepository catalogRepository,
38	                        PumpdownEventRepository eventRepository,
39	                        LevelReadingRepository levelRepository,
40	                        MissContactOrderRepository missContactRepository,
41	                        PumpCommandService pumpCommandService,
42	                        TimeProvider timeProvider) {
43	        this.catalogRepository = catalogRepository;
44	        this.eventRepository = eventRepository;
45	        this.levelRepository = levelRepository;
46	        this.missContactRepository = missContactRepository;
47	        this.pumpCommandService = pumpCommandService;
48	        this.timeProvider = timeProvider;
49	    }
50	
51	    /** 处理液位上送。 */
52	    public LevelIngestResult ingest(LevelIngestRequest request) {
53	        PumpStation station = catalogRepository.findStation(request.stationCode())
54	                .orElseThrow(() -> ApiException.unprocessable("STATION_NOT_FOUND")
55	                        .raise("泵站不存在: " + request.stationCode()));
56	        LocalDateTime receivedAt = timeProvider.now();
57	
58	        PumpdownEvent active = eventRepository.findActiveByZone(station.zoneCode()).orElse(null);
59	        if (active == null) {
60	            return handleWhenNoActiveEvent(station, request, receivedAt);
61	        }
62	        return handleDuringPumpdown(station, active, request, receivedAt);
63	    }
64	
65	    /** 无活动预降：若分区最近事件已归档且本次在归档后接收，只记迟到事件。 */
66	    private LevelIngestResult handleWhenNoActiveEvent(PumpStation station,
67	                                                      LevelIngestRequest request,
68	                                                      LocalDateTime receivedAt) {
69	        PumpdownEvent latest = eventRepository.findLatestByZone(station.zoneCode()).orElse(null);
70	        if (latest != null && latest.archived() && receivedAt.isAfter(latest.archivedAt())) {
71	            boolean inserted = levelRepository.insertLate(station.code(), request.readingTime(),
72	                    request.level(), receivedAt);
73	            return new LevelIngestResult(null, station.code(), request.readingTime(),
74	                    inserted, !inserted, true, null, null, null, null);
75	        }
76	        throw ApiException.unprocessable("NO_ACTIVE_PUMPDOWN")
77	                .raise("泵站 " + station.code() + " 所在分区无进行中的预降事件，液位无法归属");
78	    }
79	
80	    private LevelIngestResult handleDuringPumpdown(PumpStation station, PumpdownEvent event,
81	                                                   LevelIngestRequest request,
82	                                                   LocalDateTime receivedAt) {
83	        // 站点＋时刻去重：命中则原样返回，不产生任何新副作用
84	        Long existingId = levelRepository.findIdByStationAndTime(
85	                station.code(), request.readingTime());
86	        if (existingId != null) {
87	            return new LevelIngestResult(existingId, station.code(), request.readingTime(),
88	                    false, true, false, null, null, null, null);
89	        }
90	
91	        // 失联判定以本次数据之前的末次液位时刻为基准，须在插入本次数据前取
92	        LocalDateTime lastReading = levelRepository.latestReadingTimeBefore(
93	                station.code(), event.id(), request.readingTime());
94	
95	        Long readingId = levelRepository.insert(station.code(), event.id(),
96	                request.readingTime(), request.level(), receivedAt);
97	        if (readingId == null) {
98	            // 并发下站点＋时刻被抢占，按去重返回首次ID
99	            Long concurrentId = levelRepository.findIdByStationAndTime(
100	                    station.code(), request.readingTime());
101	            return new LevelIngestResult(concurrentId, station.code(), request.readingTime(),
102	                    false, true, false, null, null, null, null);
103	        }
104	
105	        AutoStop autoStop = evaluateAutoStop(station, event, request);
106	        MissContact missContact = evaluateMissContact(station, event, lastReading, request);
107	
108	        return new LevelIngestResult(readingId, station.code(), request.readingTime(),
109	                true, false, false,
110	                autoStop.taskId(), autoStop.reason(),
111	                missContact.orderId(), missContact.triggeredAt());
112	    }
113	
114	    /** 恰达目标位停泵；严格低于安全下限立即停泵（恰等下限合法不停）。 */
115	    private AutoStop evaluateAutoStop(PumpStation station, PumpdownEvent event,
116	                                      LevelIngestRequest request) {
117	        BigDecimal level = request.level();
118	        String reason;
119	        if (level.compareTo(station.safeLowLevel()) < 0) {
120	            reason = "SAFE_LOW";
121	        } else if (level.compareTo(station.targetLevel()) <= 0) {
122	            reason = "TARGET_REACHED";
123	        } else {
124	            return AutoStop.NONE;
125	        }
126	        Long taskId = pumpCommandService.autoStop(station, event, request.readingTime(), reason);
127	        return taskId == null ? AutoStop.NONE : new AutoStop(taskId, reason);
128	    }
129	
130	    /** 距末次液位恰满30分钟判定失联派单；不足30分钟不判。尚无数据时以预降开始时刻为基准。 */
131	    private MissContact evaluateMissContact(PumpStation station, PumpdownEvent event,
132	                                            LocalDateTime lastReading,
133	                                            LevelIngestRequest request) {
134	        LocalDateTime baseline = lastReading != null ? lastReading : event.startedAt();
135	        Duration gap = Duration.between(baseline, request.readingTime());
136	        if (gap.compareTo(MISS_CONTACT_AFTER) < 0) {
137	            return MissContact.NONE;
138	        }
139	        // 判定时刻为基准时刻恰满30分钟
140	        LocalDateTime triggeredAt = baseline.plus(MISS_CONTACT_AFTER);
141	        Long orderId = missContactRepository.createIfAbsent(station.code(), event.id(),
142	                baseline, triggeredAt);
143	        return new MissContact(orderId, triggeredAt);
144	    }
145	
146	    private record AutoStop(Long taskId, String reason) {
147	        static final AutoStop NONE = new AutoStop(null, null);
148	    }
149	
150	    private record MissContact(Long orderId, LocalDateTime triggeredAt) {
151	        static final MissContact NONE = new MissContact(null, null);
152	    }
