2	
3	import com.example.starter.pump.testsupport.AbstractIntegrationTest;
4	import com.example.starter.pump.testsupport.GateAtomicityProbe;
5	import com.example.starter.pump.service.PumpdownFacade;
6	import com.example.starter.pump.web.dto.WarningRequest;
7	import org.junit.jupiter.api.Test;
8	import org.springframework.beans.factory.annotation.Autowired;
9	import org.springframework.dao.DataIntegrityViolationException;
10	
11	import java.time.LocalDateTime;
12	
13	import static org.assertj.core.api.Assertions.assertThatThrownBy;
14	import static org.assertj.core.api.Assertions.assertThat;
15	
16	/**
